import{_ as e,o,c as r,a3 as s}from"./chunks/framework.CZBGEXos.js";const i="/manual/img/actividades/inicio.png",t="/manual/img/actividades/nueva-actividad.png",b=JSON.parse('{"title":"Actividades y capacitación","description":"","frontmatter":{},"headers":[],"relativePath":"modulos/actividades.md","filePath":"modulos/actividades.md"}'),n={name:"modulos/actividades.md"};function l(d,a,c,p,u,g){return o(),r("div",null,[...a[0]||(a[0]=[s('<h1 id="actividades-y-capacitacion" tabindex="-1">Actividades y capacitación <a class="header-anchor" href="#actividades-y-capacitacion" aria-label="Permalink to &quot;Actividades y capacitación&quot;">​</a></h1><p>El módulo de <strong>Actividades</strong> te permite programar y registrar todo lo que reúne a los trabajadores en torno a la seguridad: <strong>capacitaciones</strong>, <strong>charlas de inicio de jornada</strong>, <strong>ART</strong>, <strong>inspecciones</strong>, <strong>simulacros</strong> y otras actividades preventivas. Lo más importante es que aquí queda el <strong>registro de asistencia firmado</strong>, que es la prueba de que la capacitación efectivamente se realizó (una exigencia clave del DS 44, Art. 16).</p><h2 id="entrar-al-modulo" tabindex="-1">Entrar al módulo <a class="header-anchor" href="#entrar-al-modulo" aria-label="Permalink to &quot;Entrar al módulo&quot;">​</a></h2><p>En el menú lateral, haz clic en <strong>Actividades</strong>. Se abrirá la pantalla <strong>&quot;Actividades y capacitación&quot;</strong>.</p><blockquote><p>📌 Las actividades se gestionan <strong>por obra</strong>. Si ves el mensaje <em>&quot;Seleccione una obra para ver sus actividades&quot;</em>, elige primero la obra con la que quieres trabajar (en el selector de obra, normalmente arriba). Una vez seleccionada, verás sus actividades.</p></blockquote><p>La pantalla ofrece <strong>dos vistas</strong>, que alternas con los botones <strong>Lista</strong> y <strong>Calendario</strong>:</p><ul><li><strong>Lista</strong> — <em>Actividades de Hoy</em> (lo programado para el día, listo para registrar asistencia) e <em>Historial de Actividades</em> (lo ya realizado).</li><li><strong>Calendario</strong> — el mes completo de un vistazo, para coordinar la planificación (ver <a href="#el-calendario-mensual">El calendario mensual</a>).</li></ul><p><img src="'+i+'" alt="Pantalla de Actividades mostrando las actividades de hoy y el historial"></p><h2 id="tipos-de-actividad" tabindex="-1">Tipos de actividad <a class="header-anchor" href="#tipos-de-actividad" aria-label="Permalink to &quot;Tipos de actividad&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Tipo</th><th>Uso</th></tr></thead><tbody><tr><td>Charla 5 Minutos</td><td>Charla diaria de inicio de jornada</td></tr><tr><td>Análisis de Riesgos (ART)</td><td>Análisis de riesgos en terreno</td></tr><tr><td>Capacitación</td><td>Capacitaciones DS 44 (con subtipo normativo)</td></tr><tr><td>Inducción</td><td>Inducción de ingreso</td></tr><tr><td>Inspección</td><td>Inspecciones de seguridad (andamios, EPP, etc.)</td></tr><tr><td>Reunión Comité Paritario</td><td>Reuniones del CPHS</td></tr><tr><td>Simulacro de Emergencia</td><td>Simulacros programados</td></tr><tr><td>Otra actividad</td><td>Casos no contemplados; el detalle va en el título y la descripción</td></tr></tbody></table><h2 id="programar-una-actividad-nueva" tabindex="-1">Programar una actividad nueva <a class="header-anchor" href="#programar-una-actividad-nueva" aria-label="Permalink to &quot;Programar una actividad nueva&quot;">​</a></h2><ol><li>Haz clic en el botón <strong>Nueva actividad</strong>.</li><li>Completa el formulario: <ul><li><strong>Tipo de Actividad</strong> <em>(obligatorio)</em> — según la tabla anterior.</li><li><strong>Tipo de capacitación (DS44)</strong> <em>(obligatorio si es capacitación)</em> — el tipo específico que exige la normativa.</li><li><strong>Título</strong> <em>(obligatorio)</em> — un nombre claro (ej.: <em>&quot;Uso correcto de EPP&quot;</em>).</li><li><strong>Descripción</strong> <em>(opcional)</em> — de qué tratará.</li><li><strong>Relator</strong> <em>(obligatorio)</em> — quién dictará la actividad.</li><li><strong>Fecha</strong> <em>(obligatorio)</em> — cuándo se realizará.</li><li><strong>Periodicidad</strong> — si es una actividad <strong>única</strong> o se <strong>repite</strong> (en cuyo caso indicas hasta cuándo).</li><li><strong>Hora inicio</strong> <em>(obligatorio)</em> y <strong>Hora fin</strong> <em>(opcional)</em>.</li><li><strong>Ubicación</strong> <em>(opcional)</em> — dónde se hará (ej.: <em>&quot;Frente de obra, sala de charlas&quot;</em>).</li><li><strong>Trabajadores</strong> — marca quiénes deben asistir (solo aparecen los asignados a la obra).</li></ul></li><li>Guarda. La actividad quedará programada y aparecerá en la agenda de la obra.</li></ol><p><img src="'+t+'" alt="Formulario de Nueva Actividad con los campos de tipo, relator y fecha"></p><blockquote><p>💡 Por defecto el selector de asistentes muestra <strong>el grupo del relator</strong> (su cuadrilla o las cuadrillas de sus supervisores vinculados). Si necesitas convocar a más personas, activa la opción de <strong>ver toda la obra</strong>.</p></blockquote><h3 id="planificacion-diaria-charlas-y-art" tabindex="-1">Planificación diaria (charlas y ART) <a class="header-anchor" href="#planificacion-diaria-charlas-y-art" aria-label="Permalink to &quot;Planificación diaria (charlas y ART)&quot;">​</a></h3><p>Cuando el tipo es <strong>Charla 5 Minutos</strong> o <strong>ART</strong>, el formulario agrega la sección de <strong>planificación diaria</strong>, que estructura el contenido de la jornada:</p><ul><li><strong>Tema tratado</strong> <em>(obligatorio)</em> — desplegable estandarizado (fraguado, hormigonado, trabajos en altura, etc.), con opción <strong>&quot;Otro&quot;</strong> para temas fuera del catálogo.</li><li><strong>Recursos utilizados</strong> <em>(opcional)</em> — equipos y herramientas (betonera, andamio, esmeril angular…).</li><li><strong>Riesgos comunes</strong> <em>(opcional)</em> — caída a desnivel, contacto eléctrico, exposición a sílice, etc.</li><li><strong>Medidas de prevención</strong> — uso de EPP, señalización, bloqueo de energías (LOTO), etc.</li><li><strong>Tipo de trabajo</strong> (interior/exterior) y <strong>condición climática</strong>. Si el trabajo es <strong>exterior</strong>, aparece el campo de <strong>aplicación de protector solar</strong> (entre septiembre y marzo verás además un aviso de temporada de alta radiación UV).</li><li><strong>Observaciones o participación y consulta</strong> — disponible en todos los tipos; en las reuniones del Comité Paritario toma el nombre <em>&quot;Participación y consulta&quot;</em>.</li></ul><blockquote><p>Los desplegables de tema, recursos, riesgos y medidas se alimentan de los <a href="#catalogos-de-actividad">catálogos configurables de tu empresa</a>.</p></blockquote><h3 id="permisos-de-trabajo-especiales" tabindex="-1">Permisos de trabajo especiales <a class="header-anchor" href="#permisos-de-trabajo-especiales" aria-label="Permalink to &quot;Permisos de trabajo especiales&quot;">​</a></h3><p>En la misma sección puedes marcar si la jornada involucra <strong>trabajos en altura</strong>, <strong>espacios confinados</strong> o <strong>trabajo en caliente</strong>. Al marcar uno, se despliega automáticamente su <strong>formulario de permiso de trabajo</strong> con:</p><ul><li>Checklist específico del riesgo (ej. altura: arnés inspeccionado, puntos de anclaje definidos, examen de altura vigente…).</li><li><strong>Responsable</strong> del permiso, horario y ubicación.</li></ul><p>El permiso queda embebido en la actividad y aparece en el reporte posterior.</p><h2 id="planificar-el-mes-completo" tabindex="-1">Planificar el mes completo <a class="header-anchor" href="#planificar-el-mes-completo" aria-label="Permalink to &quot;Planificar el mes completo&quot;">​</a></h2><p>En lugar de crear las actividades una a una, quien tenga el permiso de <strong>planificación</strong> (Prevencionista, Jefe de Obra o quien la empresa designe) puede armar el <strong>esqueleto del mes</strong> con el botón <strong>Planificar mes</strong>:</p><ol><li>Define el <strong>rango de fechas</strong> (por defecto, el mes visible del calendario).</li><li>Agrega uno o más <strong>ítems</strong>, cada uno con: <ul><li><strong>Tipo de actividad</strong> y <strong>periodicidad</strong> (diaria de lunes a viernes, semanal o mensual).</li><li><strong>Tipo de trabajo</strong> (etapa constructiva: excavación, obra gruesa, terminaciones, entrega) — para diferenciar la planificación según el trabajo real de cada supervisor.</li><li><strong>Responsables</strong> — solo las personas a las que corresponde esa actividad (ej.: la inspección de andamios se asigna únicamente a quienes la realizan). Puedes seleccionar varios supervisores a la vez.</li><li><strong>Título base</strong>, <strong>hora</strong> y <strong>ubicación</strong> por defecto <em>(opcionales)</em> — quedan pre-llenados en cada día.</li></ul></li><li>Haz clic en <strong>Generar planificación</strong>.</li></ol><p>El sistema crea una actividad en estado <strong>borrador</strong> por cada día hábil y responsable. Los <strong>sábados y domingos se excluyen automáticamente</strong> (días no trabajados).</p><blockquote><p>💡 Cada borrador es <strong>independiente</strong>: el detalle de un día no se copia a los demás. Así, la charla del lunes puede tratar un tema distinto a la del martes. Si vuelves a generar el plan sobre el mismo rango, los días ya planificados no se duplican.</p></blockquote><h3 id="completar-un-borrador-el-responsable" tabindex="-1">Completar un borrador (el responsable) <a class="header-anchor" href="#completar-un-borrador-el-responsable" aria-label="Permalink to &quot;Completar un borrador (el responsable)&quot;">​</a></h3><p>Los responsables ven sus borradores pendientes en la sección <strong>&quot;Planificadas por completar&quot;</strong> y en el calendario (con borde punteado y el símbolo ◌). Para completar uno:</p><ol><li>Ábrelo desde la lista, el calendario o el panel del día.</li><li>Rellena el detalle de la jornada: título, tema del día, horario, ubicación y asistentes.</li><li>Guarda. El borrador pasa a <strong>programada</strong> y los asistentes convocados reciben el aviso en su bandeja de entrada.</li></ol><blockquote><p>Un supervisor también puede <strong>crear sus propias actividades</strong> cuando trabaja solo o tiene tareas adicionales no contempladas en la planificación (botón <strong>Nueva actividad</strong> o click en un día del calendario).</p></blockquote><h2 id="el-calendario-mensual" tabindex="-1">El calendario mensual <a class="header-anchor" href="#el-calendario-mensual" aria-label="Permalink to &quot;El calendario mensual&quot;">​</a></h2><p>La vista <strong>Calendario</strong> muestra el mes completo:</p><ul><li>Cada actividad aparece como una <strong>etiqueta de color según su tipo</strong> (la leyenda está al pie del calendario).</li><li>Los <strong>borradores por completar</strong> se distinguen con borde punteado y el símbolo ◌.</li><li>Los <strong>fines de semana</strong> aparecen atenuados (no se planifican actividades).</li><li>Navega entre meses con las flechas o vuelve al mes actual con <strong>Hoy</strong>.</li></ul><p>Al hacer <strong>clic en un día</strong>, se abre el panel <strong>&quot;Actividades del día&quot;</strong> con todo lo de esa fecha: las pendientes por completar aparecen primero (con una alerta que indica cuántas faltan), y desde ahí puedes <strong>completar</strong> un borrador, <strong>ver el detalle</strong> de una actividad o <strong>crear una nueva</strong> para ese día.</p><h2 id="registrar-la-asistencia" tabindex="-1">Registrar la asistencia <a class="header-anchor" href="#registrar-la-asistencia" aria-label="Permalink to &quot;Registrar la asistencia&quot;">​</a></h2><p>Una actividad solo cuenta como <strong>realizada</strong> cuando queda registrada la asistencia de los trabajadores. Hay dos formas:</p><ul><li><strong>Registrar Asistencia</strong> (el relator o gestor) — abre la lista de trabajadores y marca quiénes asistieron. Cada asistente confirma con su firma. Los que ya están registrados se muestran con la etiqueta <strong>&quot;Ya registrado&quot;</strong>.</li><li><strong>Registrar mi asistencia</strong> (el propio trabajador) — cada persona puede confirmar su asistencia y firmar desde su cuenta.</li></ul><blockquote><p>✅ La firma de asistencia es la evidencia legal de la capacitación. Sin asistencia firmada, la actividad queda como pendiente y <strong>no cuenta</strong> para el cumplimiento de la obra.</p></blockquote><h2 id="reporte-post-charla" tabindex="-1">Reporte post-charla <a class="header-anchor" href="#reporte-post-charla" aria-label="Permalink to &quot;Reporte post-charla&quot;">​</a></h2><p>En el <strong>detalle</strong> de una actividad realizada encontrarás el <strong>reporte de asistencia</strong>:</p><ul><li>Número de convocados, número de asistentes y <strong>porcentaje de asistencia</strong>.</li><li>Tabla por persona con <strong>Asistió (Sí/No)</strong> y hora de firma.</li><li>El <strong>acta completa</strong> de la jornada: planificación diaria (tema, recursos, riesgos, medidas, protector solar, observaciones) y los permisos de trabajo con su checklist.</li></ul><p>Con el botón de <strong>descarga</strong> se abre una vista imprimible que puedes guardar como PDF desde el navegador.</p><h3 id="completar-el-registro-despues-de-la-charla" tabindex="-1">Completar el registro después de la charla <a class="header-anchor" href="#completar-el-registro-despues-de-la-charla" aria-label="Permalink to &quot;Completar el registro después de la charla&quot;">​</a></h3><p>Las observaciones y los permisos suelen terminarse de anotar después de la charla. El botón <strong>Completar registro</strong> (visible para el relator o quien pueda crear actividades) permite editar la <strong>planificación diaria y los permisos de trabajo</strong> de una actividad ya realizada.</p><blockquote><p>🔒 Las <strong>asistencias y firmas nunca se modifican</strong> por esta vía: son registro de auditoría. Una vez que hay firmas, el resto del contenido de la actividad queda congelado (solo puede completarse la descripción y el acta).</p></blockquote><h2 id="catalogos-de-actividad" tabindex="-1">Catálogos de actividad <a class="header-anchor" href="#catalogos-de-actividad" aria-label="Permalink to &quot;Catálogos de actividad&quot;">​</a></h2><p>Los desplegables de <strong>temas, recursos, riesgos y medidas</strong> vienen con un set de fábrica y son <strong>configurables por empresa</strong> en el menú lateral → <strong>Catálogos</strong> (requiere permiso de gestión de la empresa). Ahí puedes agregar, renombrar o eliminar opciones de cada lista; los cambios se reflejan de inmediato en los formularios de actividad.</p><h2 id="ver-el-detalle-de-una-actividad" tabindex="-1">Ver el detalle de una actividad <a class="header-anchor" href="#ver-el-detalle-de-una-actividad" aria-label="Permalink to &quot;Ver el detalle de una actividad&quot;">​</a></h2><p>Haz clic sobre cualquier actividad para abrir su <strong>Detalle</strong>, donde verás la fecha, el horario, el relator, la descripción, la planificación diaria, los permisos de trabajo y la lista de <strong>asistentes</strong> con su estado de firma.</p><h2 id="preguntas-frecuentes" tabindex="-1">Preguntas frecuentes <a class="header-anchor" href="#preguntas-frecuentes" aria-label="Permalink to &quot;Preguntas frecuentes&quot;">​</a></h2><p><strong>No veo ninguna actividad.</strong> Probablemente no has seleccionado una obra. Las actividades se muestran <strong>por obra</strong>: elige una en el selector de obra y aparecerán sus actividades.</p><p><strong>Programé la actividad pero no aparece como cumplida.</strong> Una actividad se considera cumplida cuando tiene <strong>asistencia registrada y firmada</strong>. Mientras nadie firme la asistencia, quedará pendiente.</p><p><strong>¿Quién puede crear actividades?</strong> Los roles de gestión (Administrador, Prevencionista, Jefe de Obra, Supervisor). El relator asignado es quien la dicta. La <strong>planificación mensual</strong> requiere además el permiso de planificar, que la empresa puede delegar a otros roles (por ejemplo, representantes del Comité Paritario) desde <strong>Mi Empresa → Roles</strong>. Consulta <a href="/manual/roles/">Roles de Usuario</a>.</p><p><strong>¿Qué diferencia hay entre un borrador y una actividad programada?</strong> El <strong>borrador</strong> lo genera la planificación mensual: tiene fecha, tipo y responsable, pero le falta el detalle del día. Cuando el responsable lo <strong>completa</strong>, pasa a <strong>programada</strong> y recién entonces se convoca a los asistentes.</p><p><strong>¿Por qué el plan no generó actividades en sábado o domingo?</strong> Es intencional: los fines de semana se consideran días no trabajados y se excluyen automáticamente del rango de planificación.</p><p><strong>Un trabajador faltó a la capacitación. ¿Qué hago?</strong> Simplemente no lo marques como asistente. Quedará registrado que no asistió (aparecerá con <strong>&quot;No&quot;</strong> en el reporte), y podrás reprogramarle la capacitación más adelante.</p><p><strong>¿La asistencia se puede firmar en terreno sin señal?</strong> La firma de asistencia usa el mismo sistema de PIN de las firmas. Si no hay conexión, revisa las opciones de <a href="/manual/modulos/firmas.html">Firmas Offline</a> para recolectarlas y sincronizarlas luego.</p><p><strong>¿Cómo programo la charla diaria que se repite todos los días?</strong> Usa <strong>Planificar mes</strong>: un ítem de tipo <em>Charla 5 Minutos</em> con periodicidad <em>diaria</em> genera un borrador por cada día hábil, y cada día puede tratar su propio tema. (La opción de <strong>periodicidad</strong> del formulario de actividad individual sigue disponible para repeticiones simples.)</p>',59)])])}const v=e(n,[["render",l]]);export{b as __pageData,v as default};
